import{_ as i,C as l,o as p,c as n,j as e,a as t,E as o,a5 as c}from"./chunks/framework.CINlqUGR.js";const P=JSON.parse('{"title":"文件上传","description":"","frontmatter":{},"headers":[],"relativePath":"components/file-upload.md","filePath":"components/file-upload.md","lastUpdated":1787604392000}'),s={name:"components/file-upload.md"},h={id:"文件上传",tabindex:"-1"};function u(f,d,g,b,m,x){const r=l("Badge"),a=l("XhDemo");return p(),n("div",null,[e("h1",h,[d[0]||(d[0]=t("文件上传 ",-1)),o(r,{type:"info",text:"file-upload"}),d[1]||(d[1]=t()),d[2]||(d[2]=e("a",{class:"header-anchor",href:"#文件上传","aria-label":'Permalink to "文件上传 <Badge type="info" text="file-upload" />"'},"​",-1))]),d[3]||(d[3]=c('<p>选择文件、拖放文件，并把已选与已传的文件列出来。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>任何需要用户提交文件的地方。</li><li>需要预览、限制类型与大小、或选整个目录。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只是展示已有附件、不允许新增：用<a href="./list">列表</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>maxFiles</code> / <code>maxFileSize</code> / <code>minFileSize</code> 越界的当场被拒，<code>onFileReject</code> 逐个报出理由。</li><li><code>autoUpload</code> 决定选完就传还是等提交。</li><li><code>remoteFiles</code> 用来回显服务器上已有的附件，与本次新选的并列在同一个列表里。</li><li>上传生命周期（完成、失败）各有回调；宿主还可以插入自定的准入判断。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>投放区自己就是一个大按钮，隐藏输入是必备部件，缺了它选不了文件</p>',10)),o(a,{src:"file-upload/01-basic"}),d[4]||(d[4]=e("h3",{id:"限制与拒收",tabindex:"-1"},[t("限制与拒收 "),e("a",{class:"header-anchor",href:"#限制与拒收","aria-label":'Permalink to "限制与拒收"'},"​")],-1)),d[5]||(d[5]=e("p",null,"accept / maxFiles / maxFileSize 越界的当场被拒，file-reject 逐个报出理由",-1)),o(a,{src:"file-upload/02-limits"}),d[6]||(d[6]=e("h3",{id:"受控",tabindex:"-1"},[t("受控 "),e("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),d[7]||(d[7]=e("p",null,"传了 files 就由宿主说了算，组件自己不再落值，只发 files-change 报告意图",-1)),o(a,{src:"file-upload/03-controlled"}),d[8]||(d[8]=e("h3",{id:"禁用",tabindex:"-1"},[t("禁用 "),e("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),d[9]||(d[9]=e("p",null,"disabled 把投放区、触发器与隐藏输入一并关停，拖拽进来也不再收",-1)),o(a,{src:"file-upload/04-disabled"}),d[10]||(d[10]=e("h3",{id:"预置列表",tabindex:"-1"},[t("预置列表 "),e("a",{class:"header-anchor",href:"#预置列表","aria-label":'Permalink to "预置列表"'},"​")],-1)),d[11]||(d[11]=e("p",null,"defaultFiles 给出挂载时就在的那几份，之后列表照旧由组件自己保管，删除与清空都照常",-1)),o(a,{src:"file-upload/05-default-files"}),d[12]||(d[12]=e("h3",{id:"选整个目录",tabindex:"-1"},[t("选整个目录 "),e("a",{class:"header-anchor",href:"#选整个目录","aria-label":'Permalink to "选整个目录"'},"​")],-1)),d[13]||(d[13]=e("p",null,"directory 让隐藏输入改收目录，选中目录下的文件一次性全进来，数量上限要跟着放开",-1)),o(a,{src:"file-upload/06-directory"}),d[14]||(d[14]=e("h3",{id:"缩略图墙",tabindex:"-1"},[t("缩略图墙 "),e("a",{class:"header-anchor",href:"#缩略图墙","aria-label":'Permalink to "缩略图墙"'},"​")],-1)),d[15]||(d[15]=e("p",null,"item-preview 是个空方框，作者往里塞什么都行；塞进去的图会被裁成方格，一行摆几张由外层网格定",-1)),o(a,{src:"file-upload/07-image-wall"}),d[16]||(d[16]=e("h3",{id:"宿主自定的准入",tabindex:"-1"},[t("宿主自定的准入 "),e("a",{class:"header-anchor",href:"#宿主自定的准入","aria-label":'Permalink to "宿主自定的准入"'},"​")],-1)),d[17]||(d[17]=e("p",null,"组件只管 accept 与大小数量这几条通用规则，别的规矩由宿主在受控列表里再筛一道：这里同名文件只留最先来的那份",-1)),o(a,{src:"file-upload/08-custom-rule"}),d[18]||(d[18]=e("h3",{id:"上传生命周期",tabindex:"-1"},[t("上传生命周期 "),e("a",{class:"header-anchor",href:"#上传生命周期","aria-label":'Permalink to "上传生命周期"'},"​")],-1)),d[19]||(d[19]=e("p",null,"给一个 upload 实现组件就是上传器：收下即开传（auto-upload 可关成手动），进度、成败与返回地址都在每条的传输快照里，失败一键重试",-1)),o(a,{src:"file-upload/09-manual-upload"}),d[20]||(d[20]=e("h3",{id:"列表项上的下载",tabindex:"-1"},[t("列表项上的下载 "),e("a",{class:"header-anchor",href:"#列表项上的下载","aria-label":'Permalink to "列表项上的下载"'},"​")],-1)),d[21]||(d[21]=e("p",null,"条目里放什么由作者定：一条普通的 a[download] 就是下载口；想自己接管就换成按钮，在处理器里怎么取都行",-1)),o(a,{src:"file-upload/10-download"}),d[22]||(d[22]=e("h3",{id:"服务器附件回显",tabindex:"-1"},[t("服务器附件回显 "),e("a",{class:"header-anchor",href:"#服务器附件回显","aria-label":'Permalink to "服务器附件回显"'},"​")],-1)),d[23]||(d[23]=e("p",null,"remote-files 装编辑表单里已存在的附件：与本地文件同列渲染（allFiles 远程在前）、占 max-files 名额，删除走 remote-files-change 由宿主落库",-1)),o(a,{src:"file-upload/11-remote-files"}),d[24]||(d[24]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-file-upload&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhFileUploadClearTrigger</code> <code>XhFileUploadDropzone</code> <code>XhFileUploadHiddenInput</code> <code>XhFileUploadItem</code> <code>XhFileUploadItemDeleteTrigger</code> <code>XhFileUploadItemGroup</code> <code>XhFileUploadItemName</code> <code>XhFileUploadItemPreview</code> <code>XhFileUploadItemSizeText</code> <code>XhFileUploadLabel</code> <code>XhFileUploadRoot</code> <code>XhFileUploadTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useFileUpload</code></td></tr><tr><td>状态机</td><td><code>fileUploadMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/file-upload.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;file-upload&quot;</code>：<code>root</code> · <code>label</code> · <code>dropzone</code> · <code>trigger</code> · <strong><code>hidden-input</code></strong> · <code>item-group</code> · <code>item</code> · <code>item-name</code> · <code>item-size-text</code> · <code>item-preview</code> · <code>item-delete-trigger</code> · <code>clear-trigger</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>accept</code></td><td><code>string | string[]</code></td><td></td><td>允许的类型，写法与原生 input 的 accept 一致： &#39;image/*&#39; 这类通配、&#39;.png&#39; 这类扩展名、&#39;application/pdf&#39; 这类精确 MIME 都收， 逗号分隔的整串或数组两种形态都行（属性只表达得了整串，数组要走 property）。</td></tr><tr><td><code>maxFiles</code></td><td><code>number</code></td><td></td><td>最多留几个文件，默认 1。给 Infinity 即不限。</td></tr><tr><td><code>maxFileSize</code></td><td><code>number</code></td><td></td><td>单个文件的字节上限，默认不限。</td></tr><tr><td><code>minFileSize</code></td><td><code>number</code></td><td></td><td>单个文件的字节下限，默认 0（挡住 0 字节的空文件可以设成 1）。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验失败标注；只作用于样式与 data-invalid，不阻断收文件。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名；给了隐藏输入才参与提交。</td></tr><tr><td><code>files</code></td><td><code>File[]</code></td><td></td><td>已选文件。给定即受控：cell 直读 prop，写只发 onFilesChange 不落内部值。</td></tr><tr><td><code>defaultFiles</code></td><td><code>File[]</code></td><td></td><td></td></tr><tr><td><code>allowDrop</code></td><td><code>boolean</code></td><td></td><td>是否接受拖拽投放，默认 true。关掉后投放区不再拦默认行为，也不再出 data-dragging。</td></tr><tr><td><code>directory</code></td><td><code>boolean</code></td><td></td><td>选目录而不是选文件（隐藏输入带 webkitdirectory）。</td></tr><tr><td><code>capture</code></td><td><code>&#39;user&#39; | &#39;environment&#39;</code></td><td></td><td>移动端直接调用摄像头/麦克风采集。</td></tr><tr><td><code>remoteFiles</code></td><td><code>FileUploadRemoteFile[]</code></td><td></td><td>服务器已有附件（编辑表单回显）。给定即受控：cell 直读 prop，删改只发 onRemoteFilesChange 不落内部值。条目计入 maxFiles 总量，与本地文件一起渲染。</td></tr><tr><td><code>defaultRemoteFiles</code></td><td><code>FileUploadRemoteFile[]</code></td><td></td><td></td></tr><tr><td><code>upload</code></td><td><code>(request: FileUploadRequest) =&gt; Promise&lt;FileUploadResult | undefined | void&gt; | FileUploadResult | undefined | void</code></td><td></td><td>每个文件的传输实现。给了它组件才是上传器：收下的文件按 autoUpload 自动开传， 进度、成败与返回地址都记进该文件的传输快照。不给则维持纯选择器。</td></tr><tr><td><code>autoUpload</code></td><td><code>boolean</code></td><td></td><td>收下即自动开传，默认 true；关掉后由 api.startUpload 逐个开。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;FileUploadTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onFilesChange</code></td><td><code>(details: FileUploadFilesChangeDetails) =&gt; void</code></td><td></td><td>列表变化意图回调；受控时是唯一出口，非受控随内部写入一并通知。</td></tr><tr><td><code>onFileAccept</code></td><td><code>(details: FileUploadFileAcceptDetails) =&gt; void</code></td><td></td><td>本次收下了哪些。受控与否都发——宿主要据此发起上传。</td></tr><tr><td><code>onFileReject</code></td><td><code>(details: FileUploadFileRejectDetails) =&gt; void</code></td><td></td><td>本次拒了哪些、各自为什么。</td></tr><tr><td><code>onRemoteFilesChange</code></td><td><code>(details: FileUploadRemoteFilesChangeDetails) =&gt; void</code></td><td></td><td>远程附件列表变化意图回调；受控时是唯一出口，非受控随内部写入一并通知。</td></tr><tr><td><code>onUploadComplete</code></td><td><code>(details: FileUploadCompleteDetails) =&gt; void</code></td><td></td><td>单个文件传完（upload 的 Promise 兑现）。</td></tr><tr><td><code>onUploadError</code></td><td><code>(details: FileUploadErrorDetails) =&gt; void</code></td><td></td><td>单个文件传败（upload 的 Promise 拒绝）；中止不算失败不发。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>files-change</code></td><td><code>FileUploadFilesChangeDetails</code></td><td>列表变化；detail 为 <code>{ files: File[] }</code></td></tr><tr><td><code>remote-files-change</code></td><td><code>FileUploadRemoteFilesChangeDetails</code></td><td>远程附件列表变化；detail 为 <code>{ files: FileUploadRemoteFile[] }</code></td></tr><tr><td><code>upload-complete</code></td><td><code>FileUploadCompleteDetails</code></td><td>单个文件传完；detail 为 <code>{ file, url? }</code></td></tr><tr><td><code>upload-error</code></td><td><code>FileUploadErrorDetails</code></td><td>单个文件传败；detail 为 <code>{ file, error }</code></td></tr><tr><td><code>file-accept</code></td><td><code>FileUploadFileAcceptDetails</code></td><td>本次收下了哪些；detail 为 <code>{ files: File[] }</code></td></tr><tr><td><code>file-reject</code></td><td><code>FileUploadFileRejectDetails</code></td><td>本次拒了哪些、各自为什么；detail 为 <code>{ files: { file, reasons }[] }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhFileUploadRoot</code></td><td><code>default</code></td><td><code>FileUploadRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>item</code></td><td>uploadOf(file)?.status</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code> · <code>dragging</code></p><p><strong>事件</strong>：<code>FILES.SET</code> · <code>FILES.ADD</code> · <code>FILE.DELETE</code> · <code>FILES.CLEAR</code> · <code>PICKER.OPEN</code> · <code>DRAG.OVER</code> · <code>DRAG.LEAVE</code> · <code>DROP</code> · <code>UPLOAD.START</code> · <code>REMOTE.DELETE</code> · <code>FORM.RESET</code></p><p><strong>判据</strong>：<code>canChange</code> · <code>canDrop</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useFileUpload</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>acceptedFiles</code></td><td><code>File[]</code></td><td></td></tr><tr><td><code>remoteFiles</code></td><td><code>FileUploadRemoteFile[]</code></td><td>服务器已有附件。</td></tr><tr><td><code>allFiles</code></td><td><code>FileUploadFile[]</code></td><td>渲染顺序的完整列表：远程在前、本地在后。</td></tr><tr><td><code>dragging</code></td><td><code>boolean</code></td><td>有东西正悬在投放区上方。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>empty</code></td><td><code>boolean</code></td><td>一个文件都没有。清空按钮据此打 data-empty，空列表据此显示占位。</td></tr><tr><td><code>maxFiles</code></td><td><code>number</code></td><td>生效的数量上限（已按缺省与非法值归一）。</td></tr><tr><td><code>getFileSizeText</code></td><td><code>(file: FileUploadFile) =&gt; string</code></td><td>字节数格式化成人读的形式，供作者渲染 item-size-text；远程附件没报大小时为空串。</td></tr><tr><td><code>uploadOf</code></td><td><code>(file: FileUploadFile) =&gt; FileUploadSnapshot | null</code></td><td>该条目的传输快照：远程附件恒为 done；本地文件没配 upload 时为 null， 配了而尚未开传为 idle。</td></tr><tr><td><code>startUpload</code></td><td><code>(file: File) =&gt; void</code></td><td>手动开传（autoUpload 关着时）或失败后重试；不在列表里与传输中的调了没效果。</td></tr><tr><td><code>setFiles</code></td><td><code>(files: File[]) =&gt; void</code></td><td></td></tr><tr><td><code>addFiles</code></td><td><code>(files: File[]) =&gt; void</code></td><td></td></tr><tr><td><code>deleteFile</code></td><td><code>(file: FileUploadFile) =&gt; void</code></td><td>本地文件按引用剔除（传输中会中止），远程附件按 id 剔除。</td></tr><tr><td><code>clear</code></td><td><code>() =&gt; void</code></td><td>清空整份列表（本地与远程一起）。</td></tr><tr><td><code>openFilePicker</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;label&#39;]</code></td><td></td></tr><tr><td><code>getDropzoneProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td></td></tr><tr><td><code>getItemGroupProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: FileUploadItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemNameProps</code></td><td><code>(props: FileUploadItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemSizeTextProps</code></td><td><code>(props: FileUploadItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemPreviewProps</code></td><td><code>(props: FileUploadItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemDeleteTriggerProps</code></td><td><code>(props: FileUploadItemProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getClearTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside / inside the component</td><td>投放区、选择按钮、每条的删除按钮与清空按钮各占一个 Tab 位；禁用时投放区退出 Tab 序列，几个原生按钮带 disabled 本就不可聚焦</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on dropzone</td><td>打开系统文件选择框。投放区是 div，浏览器不会替它把这两个键合成成一次点击，连接层自己接管（并拦下空格滚屏）</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on trigger</td><td>打开系统文件选择框（原生 button 的默认激活）</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on item-delete-trigger</td><td>把这一条从列表里删掉（原生 button 的默认激活）</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on clear-trigger</td><td>清空整份列表（原生 button 的默认激活）；列表为空时按钮照常在位、可聚焦，激活是空操作</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>dropzone</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>dropzone</code></td><td><code>aria-label</code></td><td>label.dropzone</td></tr><tr><td><code>dropzone</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>dropzone</code></td><td><code>role</code></td><td>&#39;button&#39;</td></tr><tr><td><code>item-group</code></td><td><code>role</code></td><td>&#39;list&#39;</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;listitem&#39;</td></tr><tr><td><code>item-preview</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>item-delete-trigger</code></td><td><code>aria-label</code></td><td>label.deleteItem(file)</td></tr><tr><td><code>clear-trigger</code></td><td><code>aria-label</code></td><td>label.clearTrigger</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/file-upload.css</code> 按部件选择：<code>[data-scope=&quot;file-upload&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>dropzone</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>dropzone</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>dropzone</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-group</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-group</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-file-name</code></td><td>file.name</td></tr><tr><td><code>item</code></td><td><code>data-file-size</code></td><td>undefined | String(file.size) | String(file.size)</td></tr><tr><td><code>item</code></td><td><code>data-remote</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-state</code></td><td>uploadOf(file)?.status</td></tr><tr><td><code>item</code></td><td><code>data-status</code></td><td>uploadOf(file)?.status</td></tr><tr><td><code>item-name</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-size-text</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-size-text</code></td><td><code>data-file-size</code></td><td>undefined | String(file.size) | String(file.size)</td></tr><tr><td><code>item-preview</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-preview</code></td><td><code>data-file-type</code></td><td>(isRemote(file) ? file.type ?? &#39;&#39; : file.type) || &#39;un…</td></tr><tr><td><code>item-delete-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>clear-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>clear-trigger</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-file-upload-clear-bg-active</code> · <code>--xh-file-upload-clear-bg-hover</code> · <code>--xh-file-upload-clear-fg</code> · <code>--xh-file-upload-clear-fg-hover</code> · <code>--xh-file-upload-clear-font-size</code> · <code>--xh-file-upload-clear-gap</code> · <code>--xh-file-upload-clear-h</code> · <code>--xh-file-upload-clear-px</code> · <code>--xh-file-upload-clear-radius</code> · <code>--xh-file-upload-delete-bg-active</code> · <code>--xh-file-upload-delete-bg-hover</code> · <code>--xh-file-upload-delete-fg</code> · <code>--xh-file-upload-delete-fg-hover</code> · <code>--xh-file-upload-delete-radius</code> · <code>--xh-file-upload-delete-size</code> · <code>--xh-file-upload-dropzone-bg</code> · <code>--xh-file-upload-dropzone-bg-disabled</code> · <code>--xh-file-upload-dropzone-bg-dragging</code> · <code>--xh-file-upload-dropzone-border</code> · <code>--xh-file-upload-dropzone-border-dragging</code> · <code>--xh-file-upload-dropzone-border-hover</code> · <code>--xh-file-upload-dropzone-border-invalid</code> · <code>--xh-file-upload-dropzone-fg</code> · <code>--xh-file-upload-dropzone-font-size</code> · <code>--xh-file-upload-dropzone-gap</code> · <code>--xh-file-upload-dropzone-min-h</code> · <code>--xh-file-upload-dropzone-px</code> · <code>--xh-file-upload-dropzone-py</code> · <code>--xh-file-upload-dropzone-radius</code> · <code>--xh-file-upload-gap</code> · <code>--xh-file-upload-icon-size</code> · <code>--xh-file-upload-item-bg</code> · <code>--xh-file-upload-item-border</code> · <code>--xh-file-upload-item-fg</code> · <code>--xh-file-upload-item-font-size</code> · <code>--xh-file-upload-item-gap</code> · <code>--xh-file-upload-item-inner-gap</code> · <code>--xh-file-upload-item-px</code> · <code>--xh-file-upload-item-py</code> · <code>--xh-file-upload-item-radius</code> · <code>--xh-file-upload-label-fg</code> · <code>--xh-file-upload-label-fg-disabled</code> · <code>--xh-file-upload-label-font-size</code> · <code>--xh-file-upload-label-font-weight</code> · <code>--xh-file-upload-preview-bg</code> · <code>--xh-file-upload-preview-fg</code> · <code>--xh-file-upload-preview-fg-image</code> · <code>--xh-file-upload-preview-radius</code> · <code>--xh-file-upload-preview-size</code> · <code>--xh-file-upload-size-fg</code> · <code>--xh-file-upload-size-font-size</code> · <code>--xh-file-upload-trigger-bg</code> · <code>--xh-file-upload-trigger-bg-hover</code> · <code>--xh-file-upload-trigger-border</code> · <code>--xh-file-upload-trigger-fg</code> · <code>--xh-file-upload-trigger-font-size</code> · <code>--xh-file-upload-trigger-gap</code> · <code>--xh-file-upload-trigger-h</code> · <code>--xh-file-upload-trigger-px</code> · <code>--xh-file-upload-trigger-radius</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>外面套<a href="./field">表单字段</a>；缩略图墙用<a href="./image">图片</a>与<a href="./image-viewer">图片预览</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>在界面上写清楚允许的类型与大小上限，别等用户选完才拒。</li><li>拒收要说明是哪个文件、为什么。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>只拦前端不拦后端。</li><li>上传中不给进度也不能取消。</li></ul>',48))])}const U=i(s,[["render",u]]);export{P as __pageData,U as default};
